CREATE POLICY acceso_biblioteca_favoritos ON public.biblioteca_favoritos AS RESTRICTIVE FOR ALL TO authenticated USING (public.modulo_habilitado(auth.uid(), 'biblioteca')) WITH CHECK (public.modulo_habilitado(auth.uid(), 'biblioteca'));
